% 1.1

addpath('functions');

files = { ...
    'gdfs/ah7.20170613.161402.offline.mi.mi_bhbf.gdf', ...
    'gdfs/ah7.20170613.162331.offline.mi.mi_bhbf.gdf', ...
    'gdfs/ah7.20170613.162934.offline.mi.mi_bhbf.gdf'};

[s, h, sizes] = loadRuns(files);
SampleRate = h.SampleRate;

% sample rate = 512 Hz
% 17 channels
% sizes 172032, 162816, 165888
%%
lbl = labelEvents(h, sizes);

assert(all(structfun(@numel, lbl) == size(s, 1)));

cues = [771 773];
cueNames = {'both feet', 'both hands'};
assert(isequal(unique(lbl.Ak(lbl.Ak > 0))', cues));
%%
% 1.2

s = s(:, 1:end-1); % remove trigger, keep the 16 EEG channels in recorded order
[~, chLabels] = channelIndex();

L = load('lab05/laplacian16.mat');
lap = L.lap;

assert(size(s, 2) == 16);
assert(isequal(size(lap), [16 16]) && all(isfinite(lap(:))));

s_lap = s * lap;

assert(isequal(size(s_lap), size(s)) && all(isfinite(s_lap(:))));
%%
channel = channelIndex('C3');
interval = lbl.Tk == 1 & lbl.Rk == 1;
x = find(interval) ./ SampleRate;

figure; %[output:61dc2836]
ax = subplot(1, 1, 1); %[output:61dc2836]
hold(ax, 'on'); %[output:61dc2836]
plot(ax, x, s(interval, channel), 'DisplayName', 'Raw'); %[output:61dc2836]
plot(ax, x, s_lap(interval, channel), 'DisplayName', 'Laplacian'); %[output:61dc2836]
hold(ax, 'off'); %[output:61dc2836]
title(ax, sprintf('Channel %s - trial 1, run 1', chLabels{channel})); %[output:61dc2836]
xlabel(ax, 'seconds [s]'); %[output:61dc2836]
ylabel(ax, 'Amplitude [uV]'); %[output:61dc2836]
legend(ax, 'show'); %[output:61dc2836]
%%
% 1.3

muButter = [8 12];
betaButter = [18 22];
ORDER = 3;
WINDOW = 1; % s

[sfiltmu, bmu, amu] = bandpassRuns(s_lap, lbl.Rk, muButter, ORDER, SampleRate);
[sfiltbe, bbe, abe] = bandpassRuns(s_lap, lbl.Rk, betaButter, ORDER, SampleRate);

fprintf('Butterworth order %d (band-pass -> %d poles), filtfilt, per run\n', ORDER, 2 * ORDER); %[output:1aab2843]
fprintf(' - mu:   [%g %g] Hz\n', muButter); %[output:3adf4286]
fprintf(' - beta: [%g %g] Hz\n', betaButter); %[output:480e8b59]
fprintf('Moving average: %g s = %d samples, filter, per run\n', WINDOW, round(WINDOW * SampleRate)); %[output:36141442]
%%
% filterAnalyzer(bmu, amu, 'SampleRates', SampleRate);
%%
% filterAnalyzer(bbe, abe, 'SampleRates', SampleRate);
%%
% 1.4

% Power BEFORE log: input of ERD/ERS
[P_mu, sq_mu] = bandPower(sfiltmu, lbl.Rk, SampleRate, WINDOW);
[P_be, sq_be] = bandPower(sfiltbe, lbl.Rk, SampleRate, WINDOW);

fprintf('P_mu: %s, min %g, max %g uV^2\n', mat2str(size(P_mu)), min(P_mu(:)), max(P_mu(:))); %[output:7ae6f48e]
fprintf('P_be: %s, min %g, max %g uV^2\n', mat2str(size(P_be)), min(P_be(:)), max(P_be(:))); %[output:9e5ee020]
%%
% filtered EEG -> squared EEG -> smoothed power
stages = {sfiltmu, sq_mu, P_mu; sfiltbe, sq_be, P_be};
stageNames = {'filtered', 'squared', 'smoothed power'};
bandNames = {'mu', 'beta'};
stageUnits = {'[uV]', '[uV^2]', '[uV^2]'};

figure('Position', [100 100 1200 700]); %[output:20528b50]
for b = 1:size(stages, 1) %[output:group:46b8f7e8]
    for k = 1:size(stages, 2)
        ax = subplot(size(stages, 2), size(stages, 1), (k - 1) * size(stages, 1) + b); %[output:20528b50]
        plot(ax, x, stages{b, k}(interval, channel));
        title(ax, sprintf('%s - %s - %s', bandNames{b}, stageNames{k}, chLabels{channel}));
        xlabel(ax, 'seconds [s]');
        ylabel(ax, stageUnits{k});
        xlim(ax, [x(1), x(end)]);
    end
end %[output:group:46b8f7e8]
%%
% 2.1 - 2.2

% Same intervals and trimming for both bands (Lab04 rules)
[trials, Ck, RunTrial, info] = extractTrials({P_mu, P_be}, lbl, ...
    StartFrom="fixation", MaxLengthDiff=5);
[TrialPower_mu, TrialPower_be] = trials{:};

nTrials = numel(Ck);
fprintf('TrialPower: %s [samples x channels x trials]\n', mat2str(size(TrialPower_mu))); %[output:2633f6c5]
fprintf('Trial length: %d..%d samples -> kept %d\n', info.minLength, info.maxLength, size(TrialPower_mu, 1)); %[output:676bc08f]

assert(isequal(size(TrialPower_mu), size(TrialPower_be)));
assert(size(TrialPower_mu, 3) == nTrials && numel(RunTrial) == nTrials);
assert(size(unique([RunTrial info.trialInRun], 'rows'), 1) == nTrials); % no trial mixed between runs
%%
% 2.3

% Reference (fixation) and activity (feedback) periods, indices inside each trial
refPeriod = info.fixation; % [trials x 2] = [first last]
actPeriod = info.feedback;

assert(all(ismember(Ck, cues)));
assert(all(refPeriod(:, 2) >= refPeriod(:, 1)) && all(actPeriod(:, 2) >= actPeriod(:, 1)));
assert(all(refPeriod(:) >= 1 & refPeriod(:) <= size(TrialPower_mu, 1)));
assert(all(actPeriod(:) >= 1 & actPeriod(:) <= size(TrialPower_mu, 1)));

fprintf('Fixation: start %d..%d, end %d..%d\n', min(refPeriod(:, 1)), max(refPeriod(:, 1)), min(refPeriod(:, 2)), max(refPeriod(:, 2))); %[output:2c7da690]
fprintf('Feedback: start %d..%d, end %d..%d\n', min(actPeriod(:, 1)), max(actPeriod(:, 1)), min(actPeriod(:, 2)), max(actPeriod(:, 2))); %[output:77baa7ce]

countTable = zeros(numel(sizes), numel(cues));
for i = 1:numel(sizes)
    for c = 1:numel(cues)
        countTable(i, c) = nnz(RunTrial == i & Ck == cues(c));
    end
end
disp(array2table(countTable, ... %[output:group:79215969] %[output:1a71aca1]
    'VariableNames', compose('Cue_%d', cues), ... %[output:1a71aca1]
    'RowNames', compose('Run_%d', (1:numel(sizes))'))); %[output:group:79215969] %[output:1a71aca1]
%%
% 3.1 - 3.2

[ERD_ERS_mu, Reference_mu, valid_mu] = erdErs(TrialPower_mu, refPeriod);
[ERD_ERS_be, Reference_be, valid_be] = erdErs(TrialPower_be, refPeriod);

assert(isequal(size(Reference_mu), [1 size(TrialPower_mu, 2) nTrials]));

valid = valid_mu & valid_be;
fprintf('Excluded trials: %d\n', nnz(~valid)); %[output:8ba76aea]
for j = find(~valid)'
    fprintf(' - trial #%d (run %d, trial %d, cue %d)\n', j, RunTrial(j), info.trialInRun(j), Ck(j));
end

ERD_ERS_mu = ERD_ERS_mu(:, :, valid);
ERD_ERS_be = ERD_ERS_be(:, :, valid);
Ck = Ck(valid);
RunTrial = RunTrial(valid);
refPeriod = refPeriod(valid, :);
actPeriod = actPeriod(valid, :);
nTrials = numel(Ck);
%%
% 3.3

% Negative = ERD, positive = ERS. Mean over each trial's own fixation must be ~0
fixMean = zeros(nTrials, 2);
for j = 1:nTrials
    ref = refPeriod(j, 1):refPeriod(j, 2);
    fixMean(j, 1) = max(abs(mean(ERD_ERS_mu(ref, :, j), 1)));
    fixMean(j, 2) = max(abs(mean(ERD_ERS_be(ref, :, j), 1)));
end
fprintf('Max |mean ERD/ERS| over fixation: mu %g %%, beta %g %%\n', max(fixMean(:, 1)), max(fixMean(:, 2))); %[output:57940465]
assert(all(fixMean(:) < 1e-6));
%%
% 4.1 - 4.2

channel = channelIndex('C3');
fprintf('Selected channel: %s (#%d)\n', chLabels{channel}, channel); %[output:30e763da]

ERD_ERS = {ERD_ERS_mu, ERD_ERS_be};
bandNames = {'mu [8-12] Hz', 'beta [18-22] Hz'};

avg = cell(numel(ERD_ERS), 1);
sem = cell(numel(ERD_ERS), 1);
for b = 1:numel(ERD_ERS)
    [avg{b}, counts, ~, sem{b}] = cueAverage(ERD_ERS{b}(:, channel, :), Ck, cues);
end
%%
% 4.4 - timing across trials (samples from fixation onset)
cueOn = info.cueOnset(valid);
fbOn = info.feedbackOnset(valid);
fbEnd = info.length(valid) - 1; % before trimming

fprintf('Cue onset:      %.3f..%.3f s\n', min(cueOn) / SampleRate, max(cueOn) / SampleRate); %[output:6c173924]
fprintf('Feedback start: %.3f..%.3f s\n', min(fbOn) / SampleRate, max(fbOn) / SampleRate); %[output:3859f896]
fprintf('Feedback end:   %.3f..%.3f s\n', min(fbEnd) / SampleRate, max(fbEnd) / SampleRate); %[output:7dbeaa89]
%%
% 4.3 - 4.4

colors = eventColors();
t = (0:size(ERD_ERS_mu, 1)-1) ./ SampleRate; % time from fixation onset

figure('Position', [100 100 1000 800]); %[output:44c08edd]
for b = 1:numel(ERD_ERS) %[output:group:0dc7e96b]
    ax = subplot(numel(ERD_ERS), 1, b); %[output:44c08edd]
    hold(ax, 'on');
    for c = 1:numel(cues)
        m = avg{b}(:, 1, c);
        e = sem{b}(:, 1, c);
        fill(ax, [t fliplr(t)], [m + e; flipud(m - e)]', colors(cues(c)), ...
            'FaceAlpha', 0.25, 'EdgeColor', 'none', 'HandleVisibility', 'off');
        plot(ax, t, m, 'Color', colors(cues(c)), 'LineWidth', 1.5, ...
            'DisplayName', sprintf('%d %s (%d trials)', cues(c), cueNames{c}, counts(c)));
    end
    yline(ax, 0, 'k-', 'HandleVisibility', 'off');
    markTrialEvents(ax, cueOn, fbOn, SampleRate, true, actPeriod(:, 2) - 1);
    hold(ax, 'off');
    title(ax, sprintf('ERD/ERS %s - %s (mean \\pm SEM)', bandNames{b}, chLabels{channel}));
    xlabel(ax, 'time from fixation [s]');
    ylabel(ax, 'ERD/ERS [%]');
    legend(ax, 'show', 'Location', 'southwest');
    xlim(ax, [0, t(end)]);
end %[output:group:0dc7e96b]
%%
% 5.1

if isempty(which('topoplot'))
    addpath('toolboxes/eeglab');
    eeglab nogui; % adds the EEGLAB subfolders (topoplot is in functions/sigprocfunc)
end

C = load('lab05/chanlocs16.mat');
chanlocs = matchChanlocs(C.chanlocs16, chLabels); % same labels and order as the EEG channels
assert(numel(chanlocs) == size(s_lap, 2));
%%
% 5.2

% One value per channel and trial: mean over that trial's feedback (activity) / fixation (reference)
actMap = cell(numel(ERD_ERS), 1); % {band} -> [classes x channels]
refMap = cell(numel(ERD_ERS), 1);
for b = 1:numel(ERD_ERS)
    act = periodMean(ERD_ERS{b}, actPeriod); % [trials x channels]
    ref = periodMean(ERD_ERS{b}, refPeriod);
    for c = 1:numel(cues)
        actMap{b}(c, :) = mean(act(Ck == cues(c), :), 1);
        refMap{b}(c, :) = mean(ref(Ck == cues(c), :), 1);
    end
    assert(isequal(size(actMap{b}), [numel(cues) numel(chanlocs)])); % one value per channel
end
%%
% 5.3

cmap = blueWhiteRed();

figure('Position', [100 100 900 800]); %[output:8231d751]
for b = 1:numel(ERD_ERS) %[output:group:5f64ddc7]
    lim = max(abs(actMap{b}(:))); % same symmetric limits for both classes of this band
    for c = 1:numel(cues)
        ax = subplot(numel(ERD_ERS), numel(cues), (b - 1) * numel(cues) + c); %[output:8231d751]
        topoplot(actMap{b}(c, :), chanlocs, 'maplimits', [-lim lim], 'colormap', cmap, 'electrodes', 'labels');
        colormap(ax, cmap);
        clim(ax, [-lim lim]);
        cb = colorbar(ax);
        cb.Label.String = 'ERD/ERS (%)';
        title(ax, sprintf('%s - %d %s\nfeedback period (%d trials)', bandNames{b}, cues(c), cueNames{c}, counts(c)));
    end
end %[output:group:5f64ddc7]
%%
% 5.4 - validation only (not in the submitted figure): reference maps must be ~0

for b = 1:numel(ERD_ERS) %[output:group:616b7c15]
    fprintf('Max |reference map| %s: %g %%\n', bandNames{b}, max(abs(refMap{b}(:)))); %[output:9c2a8056]
    assert(all(abs(refMap{b}(:)) < 1e-6));
end %[output:group:616b7c15]

figure('Position', [100 100 900 800]); %[output:27e8818a]
for b = 1:numel(ERD_ERS) %[output:group:916e7f63]
    lim = max(abs(actMap{b}(:))); % same scale as the activity maps
    for c = 1:numel(cues)
        ax = subplot(numel(ERD_ERS), numel(cues), (b - 1) * numel(cues) + c); %[output:27e8818a]
        topoplot(refMap{b}(c, :), chanlocs, 'maplimits', [-lim lim], 'colormap', cmap, 'electrodes', 'on');
        colormap(ax, cmap);
        clim(ax, [-lim lim]);
        cb = colorbar(ax);
        cb.Label.String = 'ERD/ERS (%)';
        title(ax, sprintf('%s - %d %s\nfixation period (reference)', bandNames{b}, cues(c), cueNames{c}));
    end
end %[output:group:916e7f63]
%%
% 6 - Interpretation (Laplacian EEG, 45 trials per class, 3 runs, 1 subject)
%
% Temporal (C3, mean over feedback ~4.0-7.96 s):
% - mu: the classes have opposite sign. Both hands (773) -> ERD (mean -16%,
%   median -34%, reaching ~-34% at the end of feedback); both feet (771) -> ERS
%   (mean +32%, median +29%, growing up to ~+60% at the end of feedback).
% - beta: both classes show ERD, stronger and more consistent for hands
%   (mean -53%, minimum ~-68% at ~5.8 s) than for feet (mean -20%, median -56%).
% - The separation develops during continuous feedback: around the cue the
%   pattern is different (mu 773 ~+17%, beta 771 transient ERS up to ~+45%
%   at ~3.6-4.3 s) and the main ERD/ERS builds up ~1 s after feedback onset
%   (also delayed by the 1 s moving average).
%
% Spatial (activity maps, feedback):
% - beta 773: ERD over both hemispheres, strongest on C3 (-53%), C2/C4 (~-38%),
%   consistent with bilateral hand motor imagery.
% - beta 771: ERD strongest on Cz (-41%), where the feet area is, but also on
%   Fz/FC3/CP3 (~-30/-36%), so it is less focal.
% - mu 771: ERS on C1/C3 (+59/+32%) and ERD on CPz/Cz (-24/-17%), compatible
%   with focal ERD over the feet area and surround ERS over the hand area.
% - mu 773: ERD on C3/C1 (~-15%) is weak; the strongest value is an ERS on CPz
%   (+99%, median +67%): not the expected hand pattern, reported as observed.
%
% Limitations:
% - 45 trials per class, one subject; SEM bands are not a statistical test.
% - ERD/ERS is skewed (bounded at -100%, unbounded above): few trials dominate
%   some means (e.g. beta 771 C3: one trial at +622%, mean -20% vs median -56%).
% - Effects vary across runs (e.g. mu 771 C3: +37%, +2%, +58% in runs 1-3).
% - Event timing varies by <= 10 ms across trials, negligible here.
% - Only 16 central channels: map colors far from the electrodes are
%   interpolation, not measured values.

%[appendix]{"version":"1.0"}
